// Species sigils for the Compendium: one yokai or Taoist charm per device.
// GENERATED by mitamaos/tools/species_sigils.py - edit the shapes there and
// run `python3 species_sigils.py header > ../firmware/src/ui/species_sigils.h`.
#include "mitama_ui.h"
