    // Yokai name for each species, as shown on its Compendium card.
    inline const char* yokaiName(uint8_t t) {
        static const char* const N[Sig::T_COUNT] = {
            "Hyakume", "Raijin Fuda", "Mokumokuren", "Bagua Kagami", "Chochin-obake", "Satori",
            "Hitodama", "Fuin", "Kitsune-bi", "Onibi", "Tengu Uchiwa", "Hosho Rei",
            "Jorogumo", "Mitsudomoe Taiko", "Kirareta Shimenawa", "Nise Taiji", "Oni-men",
        };
        return t < Sig::T_COUNT ? N[t] : "?";
    }

